args.sparql:
SELECT ?city ?cityLabel 
WHERE {
  ?metro wdt:P31 wd:Q14496 ;
         wdt:P131 ?city ;
         wdt:P318 ?length .
  ?city wdt:P131 ?country ;
        wdt:P31 wd:Q515 .
  ?country wdt:P30 wd:Q46 .
  ?length wikibase:quantityValue ?lengthInMeters .
  FILTER (?lengthInMeters > 100000)
  ?city rdfs:label ?cityLabel .
  FILTER (LANG(?cityLabel) = "en")
}

